//! Audited Node-API boundary generated by the pinned napi macros.
//!
//! Constructor registration runs at native library initialization. Generated
//! callbacks validate values on their owning Env. Input buffers are copied
//! before scheduling native futures. No Env is retained. The single per-Env
//! cleanup hook touches native cancellation state only and never awaits or
//! calls JS. Updates to napi/derive require auditing these generated paths.

use crate::{
    client::{ClientState, Environment},
    error::failure,
    request::{MAXIMUM_HEADER_BYTES, MAXIMUM_INPUT_BYTES, Prepared},
    response::Exchange,
};
use napi::{
    Env, Result,
    bindgen_prelude::{AsyncBlock, AsyncBlockBuilder, Buffer, ToNapiValue},
};
use napi_derive::napi;
use std::{
    ffi::c_void,
    fmt, ptr,
    sync::Arc,
    time::{Duration, Instant},
};

fn copy_buffer(env: &Env, buffer: Buffer, maximum: usize) -> Result<Vec<u8>> {
    // SAFETY: This is the owning Env's synchronous callback. The generated
    // Buffer conversion retained this value without reading its backing bytes.
    // Converting it back only creates a local handle; no JS is invoked.
    let value = unsafe { Buffer::to_napi_value(env.raw(), buffer) }?;
    let mut kind = 0;
    let mut length = 0;
    let mut data: *mut c_void = ptr::null_mut();
    let mut backing = ptr::null_mut();
    let mut offset = 0;
    // SAFETY: All out-pointers refer to initialized, live local storage. `value`
    // is rooted in this callback's handle scope; Node returns the view's actual
    // pointer/extent/backing, without reading overridable JS properties.
    let status = unsafe {
        napi::sys::napi_get_typedarray_info(
            env.raw(),
            value,
            &mut kind,
            &mut length,
            &mut data,
            &mut backing,
            &mut offset,
        )
    };
    if status != napi::sys::Status::napi_ok || kind != napi::sys::TypedarrayType::uint8_array {
        return Err(failure(
            "InvalidArgument",
            "bytes must be an ordinary Buffer",
        ));
    }
    let mut ordinary = false;
    // SAFETY: `backing` was returned for this live typed-array view in this Env.
    // SharedArrayBuffer is deliberately not an ordinary ArrayBuffer here.
    let status = unsafe { napi::sys::napi_is_arraybuffer(env.raw(), backing, &mut ordinary) };
    if status != napi::sys::Status::napi_ok || !ordinary {
        return Err(failure(
            "InvalidArgument",
            "shared byte buffers are unsupported",
        ));
    }
    let mut detached = false;
    // SAFETY: The previous check established that this handle is an ArrayBuffer.
    let status =
        unsafe { napi::sys::napi_is_detached_arraybuffer(env.raw(), backing, &mut detached) };
    if status != napi::sys::Status::napi_ok || detached || (length != 0 && data.is_null()) {
        return Err(failure(
            "InvalidArgument",
            "detached byte buffers are unsupported",
        ));
    }
    if length > maximum {
        return Err(failure(
            "InputLimit",
            "byte input exceeds the binding limit",
        ));
    }
    if length == 0 {
        return Ok(Vec::new());
    }
    // SAFETY: Node supplied this non-null view pointer and length, including the
    // view's offset. Its ordinary, attached backing cannot be mutated/detached
    // by another Worker. No JS or await runs before the synchronous copy ends.
    Ok(unsafe { std::slice::from_raw_parts(data.cast::<u8>(), length) }.to_vec())
}

/// One ordered request or response field, retaining arbitrary value bytes.
#[napi(object)]
pub struct WireHeader {
    /// Exact request spelling or received response spelling.
    pub name: String,
    /// Field value bytes.
    pub value: Buffer,
    /// Marks a caller field sensitive for compression and diagnostics.
    pub sensitive: Option<bool>,
}

/// Explicit native client configuration.
#[napi(object)]
pub struct ClientOptions {
    /// Exact compiled catalog identifier.
    pub profile: String,
    /// Either direct or proxy.
    pub route: String,
    /// Explicit HTTP, HTTPS or SOCKS5 proxy URI.
    pub proxy: Option<String>,
    /// Explicit proxy username, supplied together with proxyPassword.
    pub proxy_username: Option<String>,
    /// Explicit proxy password, never included in errors.
    pub proxy_password: Option<String>,
    /// Enables the native cookie jar.
    pub cookies: Option<bool>,
    /// Maximum concurrent requests and unfinished bodies, from 1 to 1024.
    pub maximum_active_requests: Option<u32>,
    /// Additional DER trust roots, copied during construction.
    pub additional_roots: Option<Vec<Buffer>>,
}

/// One bounded, one-shot regular-file upload.
#[napi(object)]
pub struct FileUpload {
    /// Local UTF-8 path.
    pub path: String,
    /// Refuses a file whose initial metadata length exceeds this limit.
    pub maximum_bytes: u32,
}

/// Owned inputs for one request.
#[napi(object)]
pub struct RequestOptions {
    /// Absolute HTTP or HTTPS URL.
    pub url: String,
    /// Explicit HTTP method.
    pub method: String,
    /// Exact http1, http2 or http3 protocol.
    pub protocol: String,
    /// Explicit raw or compiled browser request context.
    pub context: String,
    /// Ordered duplicate fields.
    pub headers: Option<Vec<WireHeader>>,
    /// Replayable byte upload, limited to 16 MiB.
    pub body: Option<Buffer>,
    /// One-shot file upload instead of bytes.
    pub file: Option<FileUpload>,
    /// Total deadline from submission, including file opening and body reads.
    pub timeout_ms: Option<u32>,
}

impl fmt::Debug for WireHeader {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.debug_struct("WireHeader").finish_non_exhaustive()
    }
}

impl fmt::Debug for ClientOptions {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("ClientOptions")
            .finish_non_exhaustive()
    }
}

impl fmt::Debug for FileUpload {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.debug_struct("FileUpload").finish_non_exhaustive()
    }
}

impl fmt::Debug for RequestOptions {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("RequestOptions")
            .finish_non_exhaustive()
    }
}

/// Private module environment owner; the facade creates one per Worker.
#[derive(Debug)]
#[napi]
pub struct NativeEnvironment {
    state: Arc<Environment>,
}

#[napi]
impl NativeEnvironment {
    /// Registers native-only environment cleanup.
    #[napi(constructor)]
    pub fn new(env: Env) -> Result<Self> {
        let state = Arc::new(Environment::default());
        env.add_env_cleanup_hook(Arc::clone(&state), |state| state.close())?;
        Ok(Self { state })
    }
    /// Constructs a reusable client without caching this Env.
    #[napi]
    pub fn client(&self, env: Env, mut options: ClientOptions) -> Result<NativeClient> {
        let roots = options.additional_roots.take().unwrap_or_default();
        if roots.len() > 16 {
            return Err(failure("InputLimit", "too many additional trust roots"));
        }
        let roots = roots
            .into_iter()
            .map(|root| copy_buffer(&env, root, 1024 * 1024))
            .collect::<Result<Vec<_>>>()?;
        ClientState::build(options, roots, &self.state).map(|state| NativeClient { state })
    }
}

/// Native shared allowance for origin HTTP attempts.
#[derive(Debug)]
#[napi]
pub struct NativeAttemptBudget {
    budget: phantom::HttpAttemptBudget,
}

#[napi]
impl NativeAttemptBudget {
    /// Creates one counter shared by every request receiving this object.
    #[napi(constructor)]
    #[must_use]
    pub fn new(maximum: u32) -> Self {
        Self {
            budget: phantom::HttpAttemptBudget::new(maximum as usize),
        }
    }
    /// Returns a snapshot, not a reservation.
    #[napi(getter)]
    #[must_use]
    pub fn remaining(&self) -> u32 {
        self.budget.remaining() as u32
    }
}

/// One request's native cancellation and body owner.
#[derive(Debug)]
#[napi]
pub struct NativeCancellation {
    exchange: Arc<Exchange>,
}

#[napi]
impl NativeCancellation {
    /// Creates a handle usable by one request.
    #[napi(constructor)]
    #[must_use]
    pub fn new() -> Self {
        Self {
            exchange: Exchange::new(),
        }
    }
    /// Cancels setup, upload or response reading and drops any idle body.
    #[napi]
    pub fn cancel(&self) {
        self.exchange.cancel();
    }
}

impl Default for NativeCancellation {
    fn default() -> Self {
        Self::new()
    }
}

/// Reusable native client.
#[derive(Debug)]
#[napi]
pub struct NativeClient {
    state: Arc<ClientState>,
}

#[napi]
impl NativeClient {
    /// Copies JS-owned input before scheduling a native-owned request future.
    #[napi]
    pub fn request(
        &self,
        env: Env,
        mut options: RequestOptions,
        cancellation: &NativeCancellation,
        budget: Option<&NativeAttemptBudget>,
    ) -> Result<AsyncBlock<NativeResponse>> {
        let started = Instant::now();
        let fields = options.headers.take().unwrap_or_default();
        if fields.len() > 256 {
            return Err(failure("InputLimit", "too many request headers"));
        }
        let mut remaining = MAXIMUM_HEADER_BYTES;
        let mut headers = Vec::with_capacity(fields.len());
        for field in fields {
            remaining = remaining
                .checked_sub(field.name.len())
                .ok_or_else(|| failure("InputLimit", "request headers exceed the binding limit"))?;
            let value = copy_buffer(&env, field.value, remaining)?;
            remaining -= value.len();
            let header = phantom::RequestHeader::new(field.name, value);
            headers.push(if field.sensitive.unwrap_or(false) {
                header.sensitive()
            } else {
                header
            });
        }
        let body = options
            .body
            .take()
            .map(|body| copy_buffer(&env, body, MAXIMUM_INPUT_BYTES))
            .transpose()?;
        let prepared = Prepared::new(
            &self.state,
            options,
            headers,
            body,
            started,
            Arc::clone(&cancellation.exchange),
            budget.map(|budget| budget.budget.clone()),
        )?;
        let owner = Arc::clone(&self.state);
        AsyncBlockBuilder::new(async move {
            let (status, headers, exchange) = prepared.send().await?;
            Ok(NativeResponse {
                status,
                headers,
                exchange,
                owner,
            })
        })
        .build(&env)
    }
    /// Cancels this client's owned work, then waits for public shutdown.
    #[napi]
    pub fn close(&self, env: Env, timeout_ms: u32) -> Result<AsyncBlock<()>> {
        self.state.close();
        let shutdown = self.state.shutdown()?;
        let client = self.state.core.clone();
        AsyncBlockBuilder::new(async move {
            let _shutdown = shutdown;
            tokio::time::timeout(
                Duration::from_millis(u64::from(timeout_ms)),
                client.shutdown(),
            )
            .await
            .map_err(|_| failure("Timeout", "client shutdown deadline expired"))
        })
        .build(&env)
    }
    /// Adds a cookie through the native jar without exposing error inputs.
    #[napi]
    pub fn set_cookie(&self, url: String, cookie: String) -> Result<()> {
        self.state
            .core
            .cookie_jar()
            .ok_or_else(|| failure("CookiesDisabled", "cookie handling is disabled"))?
            .set_cookie(&url, &cookie)
            .map_err(|_| failure("InvalidCookie", "cookie could not be stored"))
    }
    /// Returns the jar's request value for this URL.
    #[napi]
    pub fn cookie_value(&self, url: String) -> Result<Option<String>> {
        self.state
            .core
            .cookie_jar()
            .ok_or_else(|| failure("CookiesDisabled", "cookie handling is disabled"))?
            .request_value(&url)
            .map_err(|_| failure("InvalidCookie", "cookie URL is invalid"))
    }
}

/// Response head and one pull-driven native body.
#[napi]
pub struct NativeResponse {
    status: u32,
    headers: Vec<(String, Vec<u8>)>,
    exchange: Arc<Exchange>,
    owner: Arc<ClientState>,
}

impl fmt::Debug for NativeResponse {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("NativeResponse")
            .field("status", &self.status)
            .finish_non_exhaustive()
    }
}

#[napi]
impl NativeResponse {
    /// HTTP status received from the peer.
    #[napi(getter)]
    #[must_use]
    pub fn status(&self) -> u32 {
        self.status
    }
    /// Response fields retaining duplicate positions and byte values.
    #[napi(getter)]
    #[must_use]
    pub fn headers(&self) -> Vec<WireHeader> {
        self.headers
            .iter()
            .map(|(name, value)| WireHeader {
                name: name.clone(),
                value: value.clone().into(),
                sensitive: None,
            })
            .collect()
    }
    /// Reads at most the requested bytes without polling ahead.
    #[napi]
    pub fn read(&self, env: Env, maximum_bytes: u32) -> Result<AsyncBlock<Option<Buffer>>> {
        let exchange = Arc::clone(&self.exchange);
        let owner = Arc::clone(&self.owner);
        AsyncBlockBuilder::new(async move {
            let _owner = owner;
            exchange
                .read(maximum_bytes)
                .await
                .map(|bytes| bytes.map(Buffer::from))
        })
        .build(&env)
    }
    /// Collects the remaining body under one exclusive reader and byte limit.
    #[napi]
    pub fn collect(&self, env: Env, maximum_bytes: u32) -> Result<AsyncBlock<Buffer>> {
        let exchange = Arc::clone(&self.exchange);
        let owner = Arc::clone(&self.owner);
        AsyncBlockBuilder::new(async move {
            let _owner = owner;
            exchange.collect(maximum_bytes).await.map(Buffer::from)
        })
        .build(&env)
    }
    /// Cancels and releases an unfinished body.
    #[napi]
    pub fn close(&self) {
        self.exchange.cancel();
    }
}

impl Drop for NativeResponse {
    fn drop(&mut self) {
        self.exchange.cancel();
    }
}

/// Lists exact compiled identifiers without maintaining a second registry.
#[napi]
#[must_use]
pub fn profile_ids() -> Vec<String> {
    phantom_profile::catalog::profiles()
        .iter()
        .map(|profile| profile.id().as_str().to_owned())
        .collect()
}
